import React from 'react'
import { useState, useEffect } from 'react'
import axios from 'axios';

axios.defaults.withCredentials=true;
const client = axios.create({
  baseURL: "https://infernovertigo.pythonanywhere.com"
})

const Add = (props) => {
  const [status, setStatus] = useState(false);
  const [buttonObj, setButtonObj] = useState("");
  const [text, setText] = useState("Add To List");

  useEffect(()=>{
    if(props.status){
      setText("Remove From List");
      setStatus(true);
    }else{
      setText("Add To List");
      setStatus(false);
    }
    //console.log(props.has)
    //console.log(props);
  }, [props.status]);

  const process_true = async(e)=>{
    const response = await client.post("/change_status", {
      title:props.title, 
      session:props.session_id, 
      csrf:props.csrf, 
      anime_id:props.anime_id,
      episodes:props.episodes
    },
    {
      headers:{
        "Content-Type":"application/json"
      }
    }).then((res)=>{
      return res.data;
    });
    if(status){
      setText("Add To List");
      setStatus(false);
    }else{
      setText("Remove From List");
      setStatus(true);
    }
  }

  /*useEffect(()=>{
    fetchData(props.id)
  }, [])*/

  return (
    <button onClick={(e)=>process_true(e)} className="feature-btns">{text}</button>
  )
}

export default Add