function getCookie(name){
  let value = "";
  let split = document.cookie.split(";");
  for(let i = 0; i < split.length; i++){
    let pair = split[i].split("=");
    let key = pair[0].trim();

    try{
      value = pair[1].trim();
    }catch{
      
    }
    
    if(name == key){
      return value;
    }
  }
  return ""
}

export {getCookie}